 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Divider rows/columns are solid 8s; the intervening regions are cells.
    rs = [i for i, row in enumerate(grid) if all(v == 8 for v in row)]
    cs = [j for j in range(w) if all(grid[i][j] == 8 for i in range(h))]
    rb = []
    start = 0
    for d in rs:
        if start < d: rb.append(list(range(start, d)))
        start = d + 1
    if start < h: rb.append(list(range(start, h)))
    cb = []
    start = 0
    for d in cs:
        if start < d: cb.append(list(range(start, d)))
        start = d + 1
    if start < w: cb.append(list(range(start, w)))
    out = [row[:] for row in grid]
    # Each pair of same-colored markers defines an axis-aligned stroke through cells.
    marks = {}
    for ri, rows in enumerate(rb):
        for ci, cols in enumerate(cb):
            vals = {grid[r][c] for r in rows for c in cols if grid[r][c] not in (0, 8)}
            if vals:
                marks[(ri, ci)] = vals
    for color in (2, 3):
        pts = [(r,c) for (r,c), vals in marks.items() if color in vals]
        if len(pts) >= 2:
            a,b = pts[0], pts[1]
            if a[0] == b[0]:
                for c in range(min(a[1],b[1]), max(a[1],b[1])+1):
                    for r0 in rb[a[0]]:
                        for c0 in cb[c]: out[r0][c0] = color
            elif a[1] == b[1]:
                for r in range(min(a[0],b[0]), max(a[0],b[0])+1):
                    for r0 in rb[r]:
                        for c0 in cb[a[1]]: out[r0][c0] = color
    # Crossings of strokes are represented by 6.
    for ri, rows in enumerate(rb):
        for ci, cols in enumerate(cb):
            if any(out[r][c] == 2 for r in rows for c in cols) and any(out[r][c] == 3 for r in rows for c in cols):
                for r in rows:
                    for c in cols: out[r][c] = 6
    return out

